#include <stdio.h>
int main() {
    double w[2] = {0, 0};
    double b = 0;
    double eta = 1.0;
    double x1[2] = {2, 2};
    int t1 = 1;
    double s = w[0]*x1[0] + w[1]*x1[1] + b;
    int y = (s >= 0) ? 1 : 0;
    int e = t1 - y;
    w[0] += eta * e * x1[0];
    w[1] += eta * e * x1[1];
    b += eta * e;
    double x2[2] = {-2, -1};
    int t2 = 0;
    s = w[0]*x2[0] + w[1]*x2[1] + b;
    y = (s >= 0) ? 1 : 0;
    e = t2 - y;
    w[0] += eta * e * x2[0];
    w[1] += eta * e * x2[1];
    b += eta * e;
    printf("%g %g %g\n", w[0], w[1], b);
    return 0;
}
